def _b7__get_ext():
    """Compile everything as one CUDA translation unit with load_inline.

    no_implicit_headers: the CUDA file includes only the ATen headers it needs
    (torch/types.h alone costs ~45 s of nvcc time).
    """
    global _b7__ext
    if _b7__ext is None:
        major, minor = torch.cuda.get_device_capability()
        sm90 = major >= 9
        arch = f"{major}{minor}a" if sm90 else f"{major}{minor}"
        skinny = _b7_CUDA_SRC.replace("@@MBAR@@", _b7_MBAR_HELPERS).replace("@@BODY@@", _b7_WG_HELPERS if sm90 else "")
        rs_defs = _b7_wgmma_rs_defs([8, 16, 32, 64, 128]) if sm90 else ""
        # Order matters only in that each route's helpers precede its kernel;
        # every route is self-contained apart from the shared helpers above.
        cuda_src = (skinny + rs_defs + _b7__tma_srcs(sm90) + _b7_MAP_SRC + _b7__gemm_src(sm90)
                    + _b7__wide_src(sm90) + _b7__sk2_src(sm90) + _b7__gq_src(sm90) + _b7__gqx_src(sm90)
                    + _b7_RGEMV_SRC + _b7__rk_src(sm90))
        _b7__ext = load_inline(
            name=f"okc_bf16proj_v141_{arch}" + (f"_dly{_b7__SK2_DELAY}" if _b7__SK2_DELAY else ""),
            cpp_sources="#include <torch/extension.h>\n" + _b7_CPP_SRC,
            cuda_sources=cuda_src,
            functions=["skinny_tma_a", "gemm90", "wide", "sk2", "gq", "gqx", "rgemv", "sgemv", "cgemv", "rk"],
            extra_cuda_cflags=["-O3", f"-gencode=arch=compute_{arch},code=sm_{arch}"] + ([f"-DSK2_DELAY_ESC={_b7__SK2_DELAY}"] if _b7__SK2_DELAY else []),
            no_implicit_headers=True,
            verbose=False,
        )
    return _b7__ext


