def _b7__iv_r24_build():
 global _b7__iv_r24_ext
 if _b7__iv_r24_ext is None:
  lines=[]
  for i,(k,r,t,a,s) in enumerate(_b7__IV_R24_CONFIGS):
   lines.append(f'if(cfg=={i}) cgemv_kernel<{r},{t},{k},{a},{s}><<<N/{r},{t}+32,0,st>>>(lp,cp,xp,tp,pmax,op,b4);')
  _b7__iv_r24_ext=load_inline(name='inv_proj_router24_candidate_v004',cpp_sources='#include <torch/extension.h>\nvoid invoke(torch::Tensor,torch::Tensor,torch::Tensor,torch::Tensor,torch::Tensor,int64_t,int64_t,int64_t);',cuda_sources=_b7__IV_R24_SRC.replace('@DISPATCH@','\n'.join(lines)),functions=['invoke'],extra_cuda_cflags=['-O3','-gencode=arch=compute_90,code=sm_90'],no_implicit_headers=True)
 return _b7__iv_r24_ext

def _b7__iv_r24_run(c,x,n,i):
 y=torch.empty((1,n),device=x.device,dtype=torch.float32)
 _b7__iv_r24_build().invoke(c['L'],c['C'],x,c['tab'],y,c['pmax'],c['base4'],i)
 return y



_b7__iv_base_prepare=_b7_prepare
_b7__iv_base_kernel=_b7_kernel_fn

def _b7__iv_choose(funcs,x,w,dev,tol):
    truth=x.double()@w.double().T
    usable=[]
    for j,fn in enumerate(funcs):
        out=fn()
        err=((out.double()-truth).norm()/truth.norm()).item()
        if err<tol:usable.append(j)
    if not usable:return 0
    graphs={}
    for j in usable:
        gr=torch.cuda.CUDAGraph()
        with torch.cuda.graph(gr):funcs[j]()
        graphs[j]=gr
    flush=torch.ones((65536,1024),device=dev,dtype=torch.float32)
    sink=torch.empty(1024,device=dev,dtype=torch.float32)
    events=[]
    for rep in range(96):
        order=usable if rep%2==0 else list(reversed(usable))
        for j in order:
            torch.sum(flush,dim=0,out=sink)
            a=torch.cuda.Event(enable_timing=True);b=torch.cuda.Event(enable_timing=True)
            a.record();graphs[j].replay();b.record();events.append((j,a,b))
    torch.cuda.synchronize()
    times={j:[] for j in usable}
    for j,a,b in events:times[j].append(a.elapsed_time(b))
    medians={j:sorted(ts)[len(ts)//2] for j,ts in times.items()}
    return min(medians,key=medians.get)

def _b7_prepare(weights):
    state=_b7__iv_base_prepare(weights)
    _b7__iv_cg_build()
    router=weights['router'];dev=router.device
    hi=router.to(torch.bfloat16);lo=(router-hi.float()).to(torch.bfloat16)
    variants=[]
    for i,(_,rows,_,_,shift) in enumerate(_b7__IV_R24_CONFIGS):
        scale=2**shift
        scaled=(lo.float()*scale).to(torch.bfloat16)
        if not bool((scaled.float()/scale==lo.float()).all()):continue
        c=_b7_cg_compress(torch.cat([hi,scaled],dim=1).contiguous(),rows)
        if c is not None:variants.append((i,c))
    gen=torch.Generator(device=dev).manual_seed(31919)
    if variants:
        _b7__iv_r24_build()
        x=torch.randn((1,8192),generator=gen,device=dev,dtype=torch.bfloat16)
        data={'x':x,'config':{'m':1,'n':256,'k':8192,'layer':'router'}}
        funcs=[lambda:_b7__iv_base_kernel(data,state)]
        funcs.extend(lambda i=i,c=c:_b7__iv_r24_run(c,x,256,i) for i,c in variants)
        best=_b7__iv_choose(funcs,x,router,dev,1e-4)
        if best:state['iv_router24']=variants[best-1]
    state['iv_cg_choice']={}
    for layer,indices in [('qkv_gate',(0,1)),('unpooler',(2,3))]:
        c=state.get('cg',{}).get(layer)
        if c is None:continue
        w=weights[layer][:1024] if layer=='unpooler' else weights[layer]
        n,k=w.shape
        x=torch.randn((1,k),generator=gen,device=dev,dtype=torch.bfloat16)
        data={'x':x,'config':{'m':1,'n':n,'k':k,'layer':layer}}
        funcs=[lambda:_b7__iv_base_kernel(data,state)]
        funcs.extend(lambda i=i:_b7__iv_cg_run(c,x,n,i) for i in indices)
        best=_b7__iv_choose(funcs,x,w,dev,1e-2)
        if best:state['iv_cg_choice'][layer]=indices[best-1]
    return state

def _b7_kernel_fn(data,state):
    layer=data['config']['layer'];m=data['x'].shape[0]
    if m==1:
        if layer=='router' and 'iv_router24' in state:
            i,c=state['iv_router24']
            return _b7__iv_r24_run(c,data['x'],data['config']['n'],i)
        if layer in state.get('iv_cg_choice',{}):
            return _b7__iv_cg_run(state['cg'][layer],data['x'],data['config']['n'],state['iv_cg_choice'][layer])
    return _b7__iv_base_kernel(data,state)
