def _b7__kshare_modules(value):
    if isinstance(value, _b7__KTypes.ModuleType):
        return _b7__KSharedModule(value)
    if isinstance(value, dict):
        return {key: _b7__kshare_modules(item) for key, item in value.items()}
    if isinstance(value, list):
        return [_b7__kshare_modules(item) for item in value]
    if isinstance(value, tuple):
        return tuple(_b7__kshare_modules(item) for item in value)
    return value


