_b7__NU_SMTRACE_TABLE_MT = {('pooler', 1): ((1, 1, 1, 2, 0, 0, 256), (1, 8, 16, 1)), ('qkv_gate', 1): ((1, 1, 1, 2, 2, 0, 256), (1, 4, 8, 4)), ('o', 1): ((1, 1, 1, 2, 0, 0, 256), (2, 4, 4, 1)), ('o', 2): ((1, 2, 1, 2, 0, 0, 256), (2, 4, 4, 1)), ('unpooler', 1): ((0, 1, 1, 2, 2, 0, 256), (1, 8, 4, 2)), ('router', 1): ((2, 1, 1, 1, 3, 0, 256), (1, 4, 4, 8))}
_b7__NU_SMTRACE_MAX_M = 32
_b7__NU_SMTRACE_TABLE_M.update({('router', 8): _b7__NU_SMTRACE_TABLE_MT['router', 1], ('qkv_gate', 8): _b7__NU_SMTRACE_TABLE_MT['qkv_gate', 1], ('pooler', 8): _b7__NU_SMTRACE_TABLE_MT['pooler', 1], ('o', 8): _b7__NU_SMTRACE_TABLE_MT['o', 1], ('unpooler', 1): _b7__NU_SMTRACE_TABLE_MT['unpooler', 1], ('unpooler', 8): _b7__NU_SMTRACE_TABLE_MT['unpooler', 1]})
