def _hh__sk(cfg):
    return cfg[8] if len(cfg) > 8 else 1


def _hh__pm(cfg):
    return cfg[9] if len(cfg) > 9 else 0


def _hh__rg(cfg):
    return cfg[10] if len(cfg) > 10 else 0


def _hh__xs(cfg):
    return cfg[11] if len(cfg) > 11 else 1


def _hh__xp(cfg):
    return cfg[12] if len(cfg) > 12 else 0


